@triton.jit
def _bin_flat(
    xp,
    yp,
    zp,
    n,
    alpha,
    MODE: tl.constexpr,
    INTMATH: tl.constexpr,
    NATIVE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """One contiguous entry, grid-strided so the 65535-program cap is moot."""
    pid = tl.program_id(0)
    step = tl.num_programs(0) * BLOCK
    i = pid * BLOCK
    while i < n:
        offs = i + tl.arange(0, BLOCK)
        m = offs < n
        if INTMATH:
            x = tl.load(xp + offs, mask=m, other=0).to(tl.int64)
            y = tl.load(yp + offs, mask=m, other=0).to(tl.int64)
        elif NATIVE:
            x = tl.load(xp + offs, mask=m, other=0.0)
            y = tl.load(yp + offs, mask=m, other=1.0)
        else:
            x = tl.load(xp + offs, mask=m, other=0.0).to(tl.float32)
            y = tl.load(yp + offs, mask=m, other=1.0).to(tl.float32)
        r = _bin_math(x, y, alpha, MODE, INTMATH)
        tl.store(zp + offs, r.to(zp.dtype.element_ty), mask=m)
        i += step


