    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    m = offs < n
    rem = offs
    dims = (d0, d1, d2, d3, d4, d5, d6, d7)
    xst = (xa0, xa1, xa2, xa3, xa4, xa5, xa6, xa7)
    yst = (ya0, ya1, ya2, ya3, ya4, ya5, ya6, ya7)
    xo = tl.zeros([BLOCK], dtype=tl.int32)
    yo = tl.zeros([BLOCK], dtype=tl.int32)
