def _pad(vals, fill=1):
    out = list(vals)
    return out + [fill] * (_MAX_DIMS - len(out))


def _launch_strided(mode, x, y, z, alpha, intmath):
    n = x.numel()
    nd = x.dim()
    if nd > _MAX_DIMS:
        raise ValueError("foreach: tensor rank above supported maximum")
    # The walk decomposes the flat index from the innermost axis outwards, so
    # the tuples handed to the kernel are reversed; padding sits past NDIM and
    # is never read.
    d = _pad(list(reversed(list(x.shape))))
    xs = _pad(list(reversed(list(x.stride()))), 0) if nd else [1] * _MAX_DIMS
    ys = _pad(list(reversed(list(y.stride()))), 0) if nd else [1] * _MAX_DIMS
    _bin_strided[(triton.cdiv(n, _BLOCK_STRIDED),)](
        x,
        y,
        z,
        n,
        alpha,
        *d,
        *xs,
        *ys,
        MODE=mode,
        INTMATH=intmath,
        NDIM=nd,
        BLOCK=_BLOCK_STRIDED,
    )


def _launch_single(mode, x, y, z, alpha, intmath, native):
    n = x.numel()
    if n == 0:
        return
    if (
        x.is_contiguous()
        and y.is_contiguous()
        and z.is_contiguous()
        and y.numel() == n
        and y.shape == x.shape
    ):
        # ``_bin_flat`` always carries three arrays (it stores through
        # ``zp`` even when that aliases ``xp``).
        blk = _plan_block(x.dtype, n, 1, 3)
        grid = (min(triton.cdiv(n, blk), _MAX_GRID),)
        _bin_flat[grid](
            x,
            y,
            z,
            n,
            alpha,
            MODE=mode,
            INTMATH=intmath,
            NATIVE=native,
            BLOCK=blk,
        )
        return
    _launch_strided(mode, x, y, z, alpha, intmath)


def _launch_fused(mode, xs, ys, zs, alpha, intmath, native, block, self_alias):
    slots = len(xs)
    n = xs[0].numel()
    blocks = triton.cdiv(n, block)
    pad = _MAX_SLOTS - slots
    common = dict(
        MODE=mode,
        EVEN=n % block == 0,
        INTMATH=intmath,
        NATIVE=native,
        SLOTS=slots,
        BLOCK=block,
    )
    if self_alias:
        _bin_fused_self[(blocks,)](
            *(xs + [xs[0]] * pad),
            *(ys + [ys[0]] * pad),
            n,
            alpha,
            **common,
        )
        return
    _bin_fused[(blocks,)](
        *(xs + [xs[0]] * pad),
        *(ys + [ys[0]] * pad),
        *(zs + [zs[0]] * pad),
        n,
        alpha,
        **common,
    )


def launch(mode, xs, ys, zs, alpha=1.0):
    """Run ``zs[i] = xs[i] <op> alpha * ys[i]`` over the whole list.

    ``zs[i]`` may alias ``xs[i]`` (the in-place forms do exactly that).
    """
    count = len(xs)
    i = 0
    while i < count:
        x = xs[i]
        y = ys[i]
        z = zs[i]
        n = x.numel()
        if n == 0:
            i += 1
            continue
        dtype = x.dtype
        intmath = mode == _MODE_SUB and not dtype.is_floating_point
        alpha_v = int(alpha) if intmath else float(alpha)
        # ``alpha == 1`` scales by exactly one, so the multiply can be dropped:
        # for a 16-bit subtraction that keeps the whole tile in the storage
        # dtype (one rounding, the same value the reference produces).
        native = (
            mode == _MODE_SUB and not intmath and alpha_v == 1.0 and dtype.itemsize <= 2
        )
        self_alias = _aliases(z, x)
        if not (
            x.is_contiguous()
            and y.is_contiguous()
            and z.is_contiguous()
            and y.numel() == n
            and z.numel() == n
            and y.shape == x.shape
            and y.dtype is dtype
        ):
            _launch_single(mode, x, y, z, alpha_v, intmath, native)
            i += 1
            continue
        j = i + 1
        while j < count and (j - i) < _MAX_SLOTS:
            if not (
                xs[j].dtype is dtype
                and ys[j].dtype is dtype
                and xs[j].is_contiguous()
                and ys[j].is_contiguous()
                and zs[j].is_contiguous()
                and xs[j].numel() == n
                and ys[j].numel() == n
                and zs[j].numel() == n
                and ys[j].shape == xs[j].shape
                and xs[j].shape == x.shape
                and _aliases(zs[j], xs[j]) == self_alias
            ):
                break
            j += 1
        block = _plan_block(dtype, n, j - i, 2 if self_alias else 3)
        if triton.cdiv(n, block) <= _MAX_GRID:
            _launch_fused(
                mode,
                xs[i:j],
                ys[i:j],
                zs[i:j],
                alpha_v,
                intmath,
                native,
                block,
                self_alias,
            )
        else:
            for k in range(i, j):
                _launch_single(mode, xs[k], ys[k], zs[k], alpha_v, intmath, native)
        i = j


