def check_tensor_list(tensors, name="self"):
    """Reproduce ATen's ``Tensor[]`` preconditions, including messages."""
    if type(tensors) is list and tensors:
        for t in tensors:
            if t.__class__ is not torch.Tensor:
                break
        else:
            return list(tensors)
    if not isinstance(tensors, (list, tuple)):
        raise TypeError(f"argument '{name}' must be tuple of Tensors")
    if len(tensors) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")
    for t in tensors:
        if not isinstance(t, torch.Tensor):
            raise TypeError(f"argument '{name}' must be tuple of Tensors")
    return list(tensors)


def same_length(a, b):
    if len(a) != len(b):
        raise RuntimeError(
            "Tensor list must have same number of elements as tensor list, "
            f"got {len(a)} and {len(b)}"
        )


def promote(a, b):
    if a is b:
        return a
    try:
        return torch.promote_types(a, b)
    except Exception:
        return a


def out_shape(a, b):
    if a.shape == b.shape:
        return a.shape
    return broadcast_shapes(a.shape, b.shape)


def broadcast_to(t, shape):
    if t.shape == shape:
        return t
    return t.expand(shape)


def broadcast_shapes(sa, sb):
    """Right-aligned shape broadcast; avoids a ``torch`` call from the host."""
    if sa == sb:
        return sa
    la, lb = len(sa), len(sb)
    out = []
    for i in range(max(la, lb)):
        da = int(sa[la - 1 - i]) if i < la else 1
        db = int(sb[lb - 1 - i]) if i < lb else 1
        if da == db or db == 1:
            out.append(da)
        elif da == 1:
            out.append(db)
        else:
            raise RuntimeError(
                f"shape {tuple(sa)} is not broadcastable with {tuple(sb)}"
            )
    return tuple(reversed(out))
